type Tok = { kind: string; text: string };
function main(): void {
  const out: Tok[] = [];
  const s = "a+b";
  for (let i = 0; i < s.length; i++) { const c = s[i]; out.push({ kind: "ch", text: c }); }
  const pairs: { a: string; b: string }[] = [];
  const m = /(\w)(\w)/.exec("xy");
  if (m) pairs.push({ a: m[1], b: m[2] });
  const m2 = /(\d+)-(\d+)/.exec("10-20");
  if (m2) { const o: { lo: number; hi: number } = { lo: Number(m2[1]), hi: Number(m2[2]) }; console.log(o); }
  console.log(out, pairs);
}
